# Generated by DevContainer Builder. Run with PowerShell 7+.
$ErrorActionPreference = 'Stop'

$env:COMPOSE_BAKE = 'false'
$env:BUILDX_BAKE_ENTITLEMENTS_FS = '0'
$Root = $PSScriptRoot
$Config = '.devcontainer/devcontainer.json'
$Engine = if ($env:DCB_ENGINE) { $env:DCB_ENGINE } else { 'docker' }
if (-not (Get-Command $Engine -ErrorAction SilentlyContinue)) { throw "Install $Engine and start its service or VM." }
if (-not (Get-Command node -ErrorAction SilentlyContinue)) { throw 'Install Node.js and the Dev Containers CLI: npm install -g @devcontainers/cli' }
$Hash = [System.Security.Cryptography.SHA256]::Create()
try { $Bytes = $Hash.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Root + [char]0 + $Config)); $Project = (-join ($Bytes | ForEach-Object { $_.ToString('x2') })).Substring(0, 24) } finally { $Hash.Dispose() }
if (-not (Get-Command devcontainer -ErrorAction SilentlyContinue)) { throw 'Install the CLI: npm install -g @devcontainers/cli' }
$EnginePath = $Engine
# PowerShell uses the native executable; the CLI cannot spawn .cmd adapters directly.
& devcontainer up --workspace-folder $Root --config (Join-Path $Root $Config) --docker-path $EnginePath --id-label "devcontainer-builder.project=$Project" @args
exit $LASTEXITCODE
